SELECT row_number() OVER (ORDER BY c.unii COLLATE "C"), c.unii, c.name, NULL
FROM h2.substance c;

SELECT row_number() OVER (ORDER BY c.slug COLLATE "C"), c.slug, c.name, NULL
FROM h2.organization c;

SELECT row_number() OVER (ORDER BY c.rxcui COLLATE "C"), c.rxcui, c.name, c.term_type
FROM h2.clinical_drug c;

SELECT row_number() OVER (ORDER BY c.product_ndc COLLATE "C"), c.product_ndc, c.name, (SELECT r.CD_VAL FROM wh.T_REF_CD r WHERE r.CD_DOM = 'DSG_FRM' AND r.CD_DSC = c.dosage_form), (SELECT r.CD_VAL FROM wh.T_REF_CD r WHERE r.CD_DOM = 'PRD_TYP' AND r.CD_DSC = c.product_type), CASE WHEN c.finished THEN 'Y' ELSE 'N' END, (SELECT w.CLIN_DRG_SK FROM wh.T_CLIN_DRG w JOIN h2.clinical_drug h ON w.RXCUI = h.rxcui WHERE h.iri = c.clinical_drug_iri LIMIT 1), NULL
FROM h2.product c;

SELECT row_number() OVER (ORDER BY c.ndc COLLATE "C"), c.ndc, (SELECT w.PRD_SK FROM wh.T_PRD_MSTR w JOIN h2.product h ON w.PRD_CD = h.product_ndc WHERE h.iri = c.product_iri LIMIT 1), (SELECT w.ORG_SK FROM wh.T_ORG_MSTR w JOIN h2.organization h ON w.ORG_CD = h.slug WHERE h.iri = c.labeler_iri LIMIT 1), c.description, c.ndc11, NULL
FROM h2.packaged_product c;

SELECT row_number() OVER (ORDER BY c.set_id COLLATE "C", c.version), c.set_id, c.version, c.effective_date
FROM h2.label c;

SELECT row_number() OVER (ORDER BY c.report_id COLLATE "C"), c.report_id, (SELECT r.CD_VAL FROM wh.T_REF_CD r WHERE r.CD_DOM = 'SRC_SYS' AND r.CD_DSC = c.source_system), to_char(c.receipt_date, 'YYYYMMDD')::integer, CASE WHEN c.serious THEN 'Y' ELSE 'N' END, CASE WHEN 'death' = ANY(c.seriousness_criteria) THEN 'Y' ELSE 'N' END, CASE WHEN 'life threatening' = ANY(c.seriousness_criteria) THEN 'Y' ELSE 'N' END, CASE WHEN 'hospitalization' = ANY(c.seriousness_criteria) THEN 'Y' ELSE 'N' END, CASE WHEN 'disabling' = ANY(c.seriousness_criteria) THEN 'Y' ELSE 'N' END, CASE WHEN 'congenital anomaly' = ANY(c.seriousness_criteria) THEN 'Y' ELSE 'N' END, CASE WHEN 'other' = ANY(c.seriousness_criteria) THEN 'Y' ELSE 'N' END, c.patient_age_years, NULL
FROM h2.adverse_event_report c;

SELECT dense_rank() OVER (ORDER BY c.recall_number COLLATE "C"), c.recall_number, CASE c.classification WHEN 'I' THEN '1' WHEN 'II' THEN '2' WHEN 'III' THEN '3' END, c.reason, to_char(c.report_date, 'YYYYMMDD')::integer, (SELECT w.ORG_SK FROM wh.T_ORG_MSTR w JOIN h2.organization h ON w.ORG_CD = h.slug WHERE h.iri = c.recalling_firm_iri LIMIT 1), (SELECT d.name FROM h2.organization d WHERE d.iri = c.recalling_firm_iri), (SELECT w.PRD_SK FROM wh.T_PRD_MSTR w JOIN h2.product h ON w.PRD_CD = h.product_ndc WHERE h.iri = rp.target_iri LIMIT 1), (SELECT d.product_ndc FROM h2.product d WHERE d.iri = rp.target_iri), NULL
FROM h2.recall c LEFT JOIN h2.recall__products rp ON rp.owner_iri = c.iri;

SELECT (SELECT w.SUBST_SK FROM wh.T_SUBST_MSTR w JOIN h2.substance h ON w.UNII_CD = h.unii WHERE h.iri = x.owner_iri LIMIT 1), (SELECT w.SUBST_SK FROM wh.T_SUBST_MSTR w JOIN h2.substance h ON w.UNII_CD = h.unii WHERE h.iri = x.moiety_iri LIMIT 1), x.source
FROM h2.substance__active_moiety x;

SELECT (SELECT w.ORG_SK FROM wh.T_ORG_MSTR w JOIN h2.organization h ON w.ORG_CD = h.slug WHERE h.iri = x.owner_iri LIMIT 1), x.name, (SELECT r.CD_VAL FROM wh.T_REF_CD r WHERE r.CD_DOM = 'ALIAS_SRC' AND r.CD_DSC = x.source), x.evidence
FROM h2.organization__aliases x;

SELECT (SELECT w.CLIN_DRG_SK FROM wh.T_CLIN_DRG w JOIN h2.clinical_drug h ON w.RXCUI = h.rxcui WHERE h.iri = x.owner_iri LIMIT 1), (SELECT w.CLIN_DRG_SK FROM wh.T_CLIN_DRG w JOIN h2.clinical_drug h ON w.RXCUI = h.rxcui WHERE h.iri = x.drug_iri LIMIT 1), x.source
FROM h2.clinical_drug__generic x;

SELECT (SELECT w.PRD_SK FROM wh.T_PRD_MSTR w JOIN h2.product h ON w.PRD_CD = h.product_ndc WHERE h.iri = o.iri LIMIT 1), (SELECT r.CD_VAL FROM wh.T_REF_CD r WHERE r.CD_DOM = 'RTE' AND r.CD_DSC = v.val)
FROM h2.product o CROSS JOIN LATERAL unnest(o.routes) AS v(val);

SELECT (SELECT w.PRD_SK FROM wh.T_PRD_MSTR w JOIN h2.product h ON w.PRD_CD = h.product_ndc WHERE h.iri = x.owner_iri LIMIT 1), x.position + 1, (SELECT w.SUBST_SK FROM wh.T_SUBST_MSTR w JOIN h2.substance h ON w.UNII_CD = h.unii WHERE h.iri = x.substance_iri LIMIT 1), x.strength_value, x.strength_unit
FROM h2.product__ingredients x;

SELECT (SELECT w.PRD_SK FROM wh.T_PRD_MSTR w JOIN h2.product h ON w.PRD_CD = h.product_ndc WHERE h.iri = x.owner_iri LIMIT 1), x.position + 1, (SELECT w.CLIN_DRG_SK FROM wh.T_CLIN_DRG w JOIN h2.clinical_drug h ON w.RXCUI = h.rxcui WHERE h.iri = x.clinical_drug_iri LIMIT 1), (SELECT r.CD_VAL FROM wh.T_REF_CD r WHERE r.CD_DOM = 'MAP_SRC' AND r.CD_DSC = x.source), x.evidence
FROM h2.product__drug_mappings x;

SELECT (SELECT w.LBL_SK FROM wh.T_LBL w JOIN h2.label h ON w.SET_ID = h.set_id AND w.VER_NO = h.version WHERE h.iri = b.owner_iri LIMIT 1), (SELECT w.PRD_SK FROM wh.T_PRD_MSTR w JOIN h2.product h ON w.PRD_CD = h.product_ndc WHERE h.iri = b.target_iri LIMIT 1)
FROM h2.label__products b;

SELECT (SELECT w.LBL_SK FROM wh.T_LBL w JOIN h2.label h ON w.SET_ID = h.set_id AND w.VER_NO = h.version WHERE h.iri = x.owner_iri LIMIT 1), x.code, x.title, x.text
FROM h2.label__sections x;

SELECT (SELECT w.AE_SK FROM wh.T_AE_HDR w JOIN h2.adverse_event_report h ON w.RPT_ID = h.report_id WHERE h.iri = x.owner_iri LIMIT 1), x.position + 1, x.drug_name, (SELECT w.CLIN_DRG_SK FROM wh.T_CLIN_DRG w JOIN h2.clinical_drug h ON w.RXCUI = h.rxcui WHERE h.iri = x.clinical_drug_iri LIMIT 1), (SELECT r.CD_VAL FROM wh.T_REF_CD r WHERE r.CD_DOM = 'DRG_ROLE' AND r.CD_DSC = x.role)
FROM h2.adverse_event_report__drugs x;

SELECT (SELECT w.AE_SK FROM wh.T_AE_HDR w JOIN h2.adverse_event_report h ON w.RPT_ID = h.report_id WHERE h.iri = d.owner_iri LIMIT 1), d.position + 1, (SELECT w.CLIN_DRG_SK FROM wh.T_CLIN_DRG w JOIN h2.clinical_drug h ON w.RXCUI = h.rxcui WHERE h.iri = b.target_iri LIMIT 1)
